import type { Plugin } from "vite";
import { readFileSync } from "fs";
import { join, resolve } from "path";

/**
 * Gives the HTML shell its default <title> and meta description from
 * site.json, so neither is hard-coded in index.html. The build-time
 * pre-render (scripts/prerender.mjs) replaces them with each route's own.
 *
 * The feeds, sitemap and llms.txt are generated by the pre-render step
 * from the same modules the app uses (utils/seo.ts).
 */
export function seoPlugin(): Plugin {
  return {
    name: "vite-plugin-seo",
    transformIndexHtml() {
      const siteConfigPath = join(resolve(process.cwd()), "content", "site.json");
      const site = JSON.parse(readFileSync(siteConfigPath, "utf-8")) as {
        name: string;
        tagline?: string;
        description?: string;
        seo?: { defaultTitle?: string; defaultDescription?: string };
      };
      const title =
        site.seo?.defaultTitle ||
        (site.tagline ? `${site.name} - ${site.tagline}` : site.name);
      const description = site.seo?.defaultDescription || site.description || "";

      return [
        { tag: "title", children: title, injectTo: "head-prepend" },
        {
          tag: "meta",
          attrs: { name: "description", content: description },
          injectTo: "head-prepend",
        },
      ];
    },
  };
}
